UPDATE fm_task_parallel_add_sign_member
SET STATUS = #{status,jdbcType=VARCHAR},
    COMMENT = #{comment,jdbcType=VARCHAR},
    COMPLETED_DATE = #{completedDate,jdbcType=TIMESTAMP},
    LOCK_VERSION = LOCK_VERSION + 1,
    UDATE = #{completedDate,jdbcType=TIMESTAMP}
WHERE OID = #{oid,jdbcType=CHAR}
  AND TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND STATUS = 'PENDING'
  AND LOCK_VERSION = #{lockVersion,jdbcType=INTEGER}
  AND #{status,jdbcType=VARCHAR} IN ('AGREED', 'DISAGREED')

UPDATE fm_task_parallel_add_sign_member
SET STATUS = 'CANCELLED', LOCK_VERSION = LOCK_VERSION + 1
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND PARALLEL_ADD_SIGN_OID = #{parallelAddSignOid,jdbcType=CHAR}
  AND STATUS = 'PENDING'

UPDATE fm_task_parallel_add_sign_member
SET MEMBER_ACCOUNT = #{targetAccount,jdbcType=VARCHAR},
    LOCK_VERSION = LOCK_VERSION + 1,
    UUSERID = #{actor,jdbcType=VARCHAR},
    UDATE = NOW()
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND OID = #{oid,jdbcType=CHAR}
  AND STATUS = 'PENDING'
  AND LOCK_VERSION = #{lockVersion,jdbcType=INTEGER}
